ControlPropertyState.AutoRuleBindingString:
UpdateContext({isProcesando: true});

If(
    IsBlank(txt_montopagar_OPL_1.Text) || Value(txt_montopagar_OPL_1.Text) <= 0,
    UpdateContext(
        {
            MostrarAviso: true,
            mensajeNotificacion: "El monto a pagar no puede estar vacío o ser negativo."
        }
    ),
        IsBlank(drp_MetodoPago_OLP_1.SelectedText.Value) || IsBlank(drp_EstadoPago_OLP_1.SelectedText.Value),
    UpdateContext(
        {
            MostrarAviso: true,
            mensajeNotificacion: "Asegurese de seleccionar el metodo de pago y el estado de pago"
        }
    ),
    IsBlank(txt_totalPOT_OLP.Text) || Value(txt_totalPOT_OLP.Text) < 0,
    UpdateContext(
        {
            MostrarAviso: true,
            mensajeNotificacion: "El total no puede ser negativo o estar vacío. Revisa los valores antes de continuar."
        }
    ),
    (drp_MetodoPago_OLP_1.SelectedText.Metodo = "Cheque" || drp_MetodoPago_OLP_1.SelectedText.Metodo = "Transferencia") && IsBlank(txt_NumTransferencia_OLP_1.Text),
    UpdateContext(
        {
            MostrarAviso: true,
            mensajeNotificacion: "El número de transferencia es obligatorio si el método de pago es Cheque o Transferencia."
        }
    ),
    // Si todas las validaciones pasan:
    UpdateContext({MostrarAviso: false}),

    Collect(
        RegistroPagos,
        {
            Fecha_Solicitud: gl_ListaContenedores_LE_2.Selected.fecha,
            Requisicion: gl_ListaContenedores_LE_2.Selected.soli_num,
            POT: gl_Contenedores_RC_4.Selected.Value,
            Codigo_Proveedor: gl_Contenedores_RC_4.Selected.txt_CodigoProvedor_OLP.Text,
            Nombre_Proveedor: gl_Contenedores_RC_4.Selected.txt_NombreProveedor_OLP.Text,
            Total_Pagar: Value(gl_Contenedores_RC_4.Selected.txt_Total_Pagar_OLP.Text),
            Total_Cancelado: Value(lbl_montoCancelado_OLP.Text),
            Total: Value(txt_totalPOT_OLP.Text),
            Fecha_UltimoPago: Today(),
            'Estado (crfb9_estado)': drp_EstadoPago_OLP_1.Selected.Value,
            Metodo_Pago: drp_MetodoPago_OLP_1.SelectedText.Metodo,
            Num_Transferencia: txt_NumTransferencia_OLP_1.Text
        }
    );
    If( 
        IsBlank(LookUp(Compras_Pots, POT = gl_Contenedores_RC_4.Selected.Value)),
        Collect(
            Compras_Pots,
            {
                Requisicion: gl_ListaContenedores_LE_2.Selected.soli_num,
                POT: gl_Contenedores_RC_4.Selected.Value,
                Total: Value(lbl_montoTotal_OLP.Text),
                'Estado (crfb9_estado)': drp_EstadoPago_OLP_1.Selected.Value,
                Num_Vend: gl_Contenedores_RC_4.Selected.txt_CodigoProvedor_OLP.Text,
                Provedor: gl_Contenedores_RC_4.Selected.txt_NombreProveedor_OLP.Text
            }
        ),
        LookUp(Compras_Pots, POT = gl_Contenedores_RC_4.Selected.Value).'Estado (crfb9_estado)' = "Parcial" && Value(txt_totalPOT_OLP.Text) = 0,
        Patch(
            Compras_Pots,
            LookUp(Compras_Pots, POT = gl_Contenedores_RC_4.Selected.Value),
            {
                'Estado (crfb9_estado)': drp_EstadoPago_OLP_1.Selected.Value
            }
        )
    );
    Refresh(RegistroPagos);

    If(
        Sum(
            gl_Contenedores_RC_4.AllItems,
            txt_Total_Pagar_OLP.Text 
        ) - Value(lbl_montoCancelado_OLP.Text) = 0,
        Patch(
            Solicitud_Compras,
            LookUp(
                Solicitud_Compras,
                soli_num = gl_ListaContenedores_LE_2.Selected.soli_num
            ),
            {estado: "Cancelado"}
        )
    );

    Reset(drp_MetodoPago_OLP_1);
    Reset(drp_EstadoPago_OLP_1);
    Reset(txt_montopagar_OPL);
    Reset(txt_NumTransferencia_OLP_1);

    UpdateContext({AbrirConfirmar: false});    
    UpdateContext({isProcesando: false});
    UpdateContext({AbrirC: false, Disable: false})
);

