Refresh(Solicitud_Compras)

UpdateContext({AbrirConfirmar: false, Disable: false});
    Reset(drp_MetodoPago_OLP_1);
    Reset(drp_EstadoPago_OLP_1);
    Reset(txt_NumTransferencia_OLP_1)

If(
    CountRows(colSelectedPOTs) = 0,
    UpdateContext(
        {
            MostrarAviso: true,
            mensajeNotificacion: "Selecciona al menos un POT"
        }
    ),
    CountRows(
        Distinct(
            colSelectedPOTs,
            Moneda
        )
    ) > 1,
    UpdateContext(
        {
            MostrarAviso: true,
            mensajeNotificacion: "No se pueden seleccionar POTs con diferentes Tipos de cambio (USD, CRC). Por favor seleccione solo un tipo."
        }
    ),
    Concurrent(
        ClearCollect(
            colPOTtoProcess,
            ForAll(
                colSelectedPOTs,
                {
                    POT: ThisRecord.POT,
                    MontoAPagar: ThisRecord.MontoAPagar,
                    Moneda: ThisRecord.Moneda,
                    Codigo_Proveedor: ThisRecord.Codigo_Proveedor,
                    Nombre_Proveedor: ThisRecord.Nombre_Proveedor,
                    Num_Referencia: ""
                }
            )
        ),
        UpdateContext(
            {
                AbrirConfirmar: true,
                Disable: true
            }
        )
    )
)

Collect(
    colSelectedPOTs,
    {
        POT: ThisItem.Value,
        MontoAPagar: Value(txt_Total_Pagar_OLP.Text),
        Moneda: Coalesce(
            Upper(
                LookUp(
                    vendor,
                    vend_num = LookUp(
                        po,
                        po_num = ThisItem.Value,
                        vend_num
